+fn spawn_deliveries(
+    tasks: &mut JoinSet<()>,
+    client: Client,
+    routes: Arc<EndpointRoutes>,
+    semaphore: Arc<Semaphore>,
+    delivery: DeliveryConfig,
+    event: LogEvent,
