+
+async fn deliver_with_retry(
+    client: Client,
+    endpoint: Arc<Endpoint>,
+    body: Vec<u8>,
+    event_name: String,
+    delivery_id: String,
+    delivery: DeliveryConfig,
+) {
+    for attempt in 1..=delivery.max_attempts {
+        match send_once(&client, &endpoint, &body, &event_name, &delivery_id).await {
+            Ok(status) if status.is_success() => return,
+            Ok(status) => {
+                if !is_retriable_status(status) || attempt == delivery.max_attempts {
+                    error!(
+                        endpoint = %endpoint.name,
+                        event = %event_name,
+                        delivery_id = %delivery_id,
+                        attempts = attempt,
+                        status = %status,
+                        "HttpLogger: webhook delivery failed"
+                    );
+                    return;
+                }
+                warn!(
+                    endpoint = %endpoint.name,
+                    event = %event_name,
+                    delivery_id = %delivery_id,
+                    attempt,
+                    status = %status,
+                    "HttpLogger: webhook delivery retrying"
+                );
+            }
+            Err(err) => {
+                if attempt == delivery.max_attempts {
+                    error!(
+                        endpoint = %endpoint.name,
+                        event = %event_name,
+                        delivery_id = %delivery_id,
+                        attempts = attempt,
+                        error = %err,
+                        "HttpLogger: webhook delivery failed"
+                    );
+                    return;
+                }
+                warn!(
+                    endpoint = %endpoint.name,
+                    event = %event_name,
+                    delivery_id = %delivery_id,
+                    attempt,
+                    error = %err,
+                    "HttpLogger: webhook delivery retrying"
+                );
+            }
+        }
+
+        tokio::time::sleep(backoff_duration(&delivery, attempt)).await;
+    }
